      for(const[label,keys]of groups){const c=input('','checkbox'),l=el('label','', 'check');l.append(c,el('span',label+' · '+keys.filter(k=>JSON.stringify(this.app.config[k])!==JSON.stringify(cfg[k])).length+' changed fields'));box.append(l);checks.push({c,keys});}
