      if(p.textSize)css.push('body,.post-row,.thread-right{font-size:'+p.textSize+'px!important}');
      if(p.countSize)css.push('.post-count{font-size:'+p.countSize+'px!important}');
      for(const[key,selector,property]of[['leftWidth','.thread-left','width'],['rightWidth','.thread-right','width'],['composerHeight','.composer-bar textarea','height']])if(p[key])css.push(selector+'{'+property+':'+p[key]+'px!important;'+(property==='width'?'flex:0 0 '+p[key]+'px!important;min-width:0!important;max-width:75vw!important;':'min-height:0!important;')+'}');
      if(p.density!=='native')css.push('.post-row{padding-top:'+(p.density==='compact'?2:9)+'px!important;padding-bottom:'+(p.density==='compact'?2:9)+'px!important}');
