      for(const[key,label]of[['font','Site font'],['countFont','Count font']]){const s=select(fonts,p[key]);s.ariaLabel=label;s.addEventListener('change',()=>{p[key]=s.value;save();});fontFields.append(field(label,s));}
      const sizes=grid(appearance);number(sizes,'textSize','Text size',11,24);number(sizes,'countSize','Count size',10,48);
      const density=select([['native','Site default'],['compact','Compact'],['comfortable','Comfortable']],p.density);density.addEventListener('change',()=>{p.density=density.value;save();});appearance.append(field('Post spacing',density));
      const add=details(appearance,'Custom fonts'),family=input();family.placeholder='Font name';family.ariaLabel='Installed font name';family.maxLength=80;
      const addFont=f=>{if(p.fonts.length>=8&&!p.fonts.some(x=>x.name===f.name)){status.textContent='Remove a font before adding another.';return;}p.fonts=p.fonts.filter(x=>x.name!==f.name);p.fonts.push(f);p.font=f.name;save();this.app.ui.render();};
      add.append(line(family,button('Add',()=>{const name=family.value.trim();if(!/^[\w .-]{1,80}$/.test(name)){status.textContent='Enter a font name.';return;}addFont({name});})),button('Upload font',async()=>{try{const f=await DXUI.upload('.woff,.woff2');if(!f)return;if(f.size>256000)throw new Error('Choose a font smaller than 250 KB.');const bytes=new Uint8Array(await f.arrayBuffer()),sig=String.fromCharCode(...bytes.slice(0,4));if(!['wOFF','wOF2'].includes(sig))throw new Error('Choose a WOFF or WOFF2 font.');const name=f.name.replace(/\.woff2?$/i,'').replace(/[^\w .-]/g,' ').trim().slice(0,80)||'Custom font';let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.slice(i,i+8192));addFont({name,data:'data:font/'+(sig==='wOF2'?'woff2':'woff')+';base64,'+btoa(binary)});}catch(e){status.textContent=e.message;}}));
      for(const f of p.fonts)add.append(line(el('span',f.name),button('Remove',()=>{p.fonts=p.fonts.filter(x=>x.name!==f.name);if(p.font===f.name)p.font='';if(p.countFont===f.name)p.countFont='';const face=this.fonts.get(f.name);if(face)document.fonts?.delete(face);this.fonts.delete(f.name);save();this.app.ui.render();},'tiny')));
      reset(appearance,['font','countFont','textSize','countSize','density'],'Reset appearance');
      this.app.topbar.renderPreferences(sections.get('topbar'),p,save);
      const layout=sections.get('layout');layout.append(el('h2','Right sidebar'));const sidebarChecks=checks(layout);for(const name of nativeTabs)this.check(sidebarChecks,name,p.sidebar,name,save);
      const panels=details(layout,'Panel sizes'),panelGrid=grid(panels);number(panelGrid,'leftWidth','Thread list width',140,360,10);number(panelGrid,'rightWidth','Right sidebar width',220,640,10);number(panelGrid,'composerHeight','Composer height',32,200,4);
      reset(layout,['sidebar','leftWidth','rightWidth','composerHeight'],'Reset layout');
      const stats=sections.get('stats'),settings=p.stats;stats.append(el('h2','Activity numbers'));const cards=checks(stats);
      for(const[id,label]of[['counts','Counts'],['accuracy','Accuracy'],['days','Active days'],['bestDay','Best day'],['mistakes','Mistakes'],['average','Daily average'],['bestWeek','Best seven days'],['dayRun','Longest daily streak']]){const c=input('','checkbox');c.checked=settings.cards.includes(id);const l=el('label','', 'check');l.append(c,el('span',label));c.addEventListener('change',()=>{const next=c.checked?[...settings.cards,id]:settings.cards.filter(k=>k!==id);if(!next.length||next.length>6){c.checked=!c.checked;status.textContent='Choose between 1 and 6 activity numbers.';return;}settings.cards=next;save();});cards.append(l);}
      const rowCount=select([[10,'10'],[25,'25'],[50,'50'],[100,'100']],String(settings.rows));rowCount.ariaLabel='Leaderboard rows';rowCount.addEventListener('change',()=>{settings.rows=Number(rowCount.value);save();});stats.append(field('Leaderboard rows',rowCount));
      const chart=details(stats,'Chart appearance'),chartGrid=grid(chart),color=input(settings.accent||'#f97316','color');color.ariaLabel='Stats color';color.addEventListener('change',()=>{settings.accent=color.value;save();});chartGrid.append(field('Accent color',color));const chartSize=input(settings.chartHeight,'number');chartSize.min=120;chartSize.max=320;chartSize.ariaLabel='Chart height';chartSize.addEventListener('change',()=>{settings.chartHeight=DXCore.clamp(Math.round(Number(chartSize.value)||180),120,320);chartSize.value=settings.chartHeight;save();});chartGrid.append(field('Chart height',chartSize));this.check(chart,'Chart grid',settings,'grid',save);chart.append(button('Use site color',()=>{settings.accent='';color.value='#f97316';save();}));reset(stats,['stats'],'Reset stats display');
      const more=sections.get('more'),behavior=checks(more);const toggle=(host,label,key,fn)=>this.app.ui.checkbox(host,label,key,fn);toggle(behavior,'Remember thread tabs','rememberTabs');toggle(behavior,'Refresh counting.gg totals','sync');const shortcuts=details(more,'Keyboard shortcuts');toggle(shortcuts,'Enable shortcuts','shortcuts');const keys=el('dl','', 'prefs-shortcuts');for(const[label,key]of[['Preferences','Alt+Shift+D'],['Focus composer','Alt+Shift+F'],['Reset appearance','Alt+Shift+Backspace']])keys.append(el('dt',label),el('dd',key));shortcuts.append(keys);
      const backup=details(more,'Backup and restore');backup.append(hint('Includes settings, streaks, observed posts and processed history.'),line(button('Download backup',this.app.ui.guard(()=>this.app.exportBackup())),button('Restore backup',this.app.ui.guard(async()=>{const f=await DXUI.upload();if(!f)return;if(f.size>250e6)throw new Error('Choose a backup smaller than 250 MB.');const config=await this.app.importBackup(JSON.parse(await f.text()));this.app.streaks.liveCache?.clear();this.app.streaks.changed();this.app.revision++;this.app.cache=null;this.app.ui.previewSettings(config);this.app.ui.setStatus('Backup imported. Choose settings to restore.');}))));
      const about=details(more,'About');about.append(el('p','Dyslexus Extension · 1.0'),button('Introduction',()=>this.app.intro.open()));
      const help=details(more,'Troubleshooting');help.append(button('Refresh totals',this.app.ui.guard(async()=>{await this.app.sync.totals(true);const thread=this.app.adapter.context().thread;if(thread&&this.app.config.preferences.topbar.items.includes('rankup'))await this.app.sync.board(thread,true);})),button('Show details',()=>this.app.ui.open('Diagnostics')),line(button('Reset all appearance and layout',()=>{this.app.restoreNative();this.app.ui.render();})));
