  function speedDuration(ms){if(!Number.isFinite(ms))return'—';if(ms<1000)return Number(ms.toFixed(3))+' ms';const hours=Math.floor(ms/3600000),minutes=Math.floor(ms/60000)%60,seconds=Number(((ms%60000)/1000).toFixed(3));return(hours?hours+'h ':'')+(minutes?minutes+'m ':'')+seconds+'s';}
